  ('cozumel-mexico', '10S', 'Cozumel', 'Mexico', 'Cozumel drift diving', 'live', 'verified', 'oceanAerial', 'Quintana Roo (Cancún & Riviera Maya)', '{"diveglobal","liveaboard","ocean"}', '{}', '{"essential","comfort","premier"}', null, null, '{"key_facts":["Reefs sit on the Mesoamerican Barrier Reef (Great Mayan Reef); drift diving averages ~1.5 knots","Signature walls: Palancar (accessible), Santa Rosa (expert), Columbia Deep","Parque Nacional Arrecifes de Cozumel reef bracelet = MX$220 (~US$13) per person per day (Jan 2026)","Multiple recompression chambers on-island: SSS/Int''l Hospital + Costamed (DAN preferred provider)","Banco Chinchorro (largest W-hemisphere atoll) is ~30-35 nm off Costa Maya, launched from Xcalak/Mahahual - NOT Cozumel"],"safety":{"emergency":"911","hospital":"Costamed / Cozumel International / Medica San Miguel / General Hospital (town); serious trauma to Cancun private hospitals or US air-evac","recompression_chambers":[{"name":"SSS Recompression Chamber / Medicina Hiperbarica Integral","address":"Calle 5 Sur #21-B, Centro, Cozumel QR 77600","phone":"+52 (987) 872-1430 / 872-2387","emergency_24h":"(987) 103-5524","network":"IDAN Referral Center / UHMS / EUBS"},{"name":"Costamed Hyperbaric Center (Cozumel Medical Center)","opened":"Nov 2013","network":"DAN Recompression Chamber Network Preferred Provider"}],"dan_emergency":"+1-919-684-9111","malaria":"extremely low / none in tourist zone","dengue":"active - Quintana Roo among highest-activity states 2026; chikungunya/Zika also circulate","water":"bottled/purified only","hurricane":"Jun-Nov (peak Aug-Oct)","dive_no_fly":"12h single / 18h multi-day / 24h deco (DAN); use 24h conservative given repetitive day-boat profiles","drift_diving":"briefing required; SMB; dive within cert; Santa Rosa Wall expert-only","chinchorro":"no chamber at atoll; nearest chambers hours away on mainland/Cozumel - extra-conservative profiles + DAN cover","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture":"all-but-essential","except":["airside transit through Tijuana airport","the Cross Border Xpress bridge linking the airport across the border","federal toll road 1D and the Via Rápida through Tijuana to the border"]},{"name":"The city of Tecate in Baja California, including roads between Tijuana and Tecate","lvl":3,"posture":"all-but-essential"},{"name":"The state of Chihuahua","lvl":3,"posture":"all-but-essential","except":["the city of Chihuahua","the border crossing in Ciudad Juárez via federal toll road 45","federal toll road 45D between Chihuahua and Ciudad Juárez","the Copper Canyon rail route and the towns immediately on it, including Creel","the road from Creel via San Juanito to San Pedro","state highway 16 from San Pedro to Chihuahua"],"note":"The advisory also covers the areas south-west of road 45D."},{"name":"The state of Sinaloa","lvl":3,"posture":"all-but-essential","except":["the cities of Los Mochis and Mazatlán","road 32 between El Fuerte and Los Mochis","the 15D federal toll road running the length of the state","the Copper Canyon rail route to and from Los Mochis and El Fuerte, and the towns immediately on it"]},{"name":"The state of Tamaulipas","lvl":3,"posture":"all-but-essential","except":["the border crossing at Nuevo Laredo via federal toll road 85D from Monterrey","federal highways 80, 81 and 85 between Tampico, Ciudad Victoria and Magueyes","the area of Tamaulipas south of those highways"]},{"name":"The state of Zacatecas","lvl":3,"posture":"all-but-essential"},{"name":"In Guanajuato: the areas south-west of road 45D","lvl":3,"posture":"all-but-essential","note":"FCDO advises against all but essential travel to the areas south-west of road 45D. (San Miguel de Allende and Guanajuato City sit outside this area.)"},{"name":"The state of Michoacán","lvl":3,"posture":"all-but-essential","except":["the city of Morelia via federal toll roads 15D, 126 and 43","toll road 48D between Morelia and its airport","the town of Pátzcuaro via toll roads 14D and 15 from Morelia, and boat trips on Lake Pátzcuaro","Federal Highway 15D"]},{"name":"In Jalisco: the areas south and south-west of Lake Chapala to the Colima border","lvl":3,"posture":"all-but-essential","note":"Thirty-nine named municipalities, including Autlán de Navarro, Sayula, Tapalpa, Cocula and Villa Corona — the advisory lists each by name."},{"name":"In Jalisco: eleven northern municipalities","lvl":3,"posture":"all-but-essential","note":"Bolaños, Chimaltitán, Colotlán, Hostotipaquillo, Huejúcar, Huequilla el Alto, Mezquitic, San Martín de Bolaños, Santa María de los Ángeles, Totatiche and Villa Guerrero."},{"name":"The state of Colima","lvl":3,"posture":"all-but-essential","except":["the city of Manzanillo by sea, or by air via Manzanillo-Costalegre International Airport","direct travel via road 200 from that airport to Manzanillo"]},{"name":"The state of Guerrero, including the city of Acapulco","lvl":3,"posture":"all-but-essential","except":["the town of Zihuatanejo/Ixtapa accessed by air"]},{"name":"Within 40km of the Guatemalan border, from the Pacific Coast up to and including the Gracias a Dios crossing","lvl":3,"posture":"all-but-essential"},{"name":"Federal Highway 199 between Rancho Nuevo, outside San Cristóbal de las Casas, and the Chancalá junction outside Palenque","lvl":3,"posture":"all-but-essential","note":"The restriction is the highway segment, not the towns at either end."}],"dive_emergency_numbers_verified":{"read":"2026-08-30","numbers":{"+1-919-684-9111":"DAN 24/7 emergency hotline — dan.org/about-dan/contact/, read 2026-08-30"},"_rule":"Each number above was read from the authority named beside it on the date shown. ⛔ A number with no entry here has NOT been verified and must not be presented as an emergency contact."}},"timing":{"peak":"Dec-Mar (calmest seas, clearest skies, 200ft+ viz; Dec24-Jan1 crowded/expensive spike)","shoulder":"Nov (~25-40% off Dec) and May (~20-30% off April); near-peak conditions","green":"May-Sep warmest water ~27-28C / calmest seas; summer humidity + hurricane risk Jun-Nov (peak Aug-Oct)","out_of_season_fill_the_beds":"green-summer value story: warmest/calmest water + 20-40% off rooms, thinner crowds, pair with hurricane trip insurance","fire_date":"open peak-season campaign Aug-Sep for Dec-Mar; shoulder push Sep-Oct (Nov) and Feb-Mar (May); Carnival micro-campaign Nov-Dec for mid-Feb","event_peaks":["Cozumel Carnival 2026: main parades Feb 14/15/17 (Fat Tue), run Feb 11-18, pre-Carnival Jan 17-Feb 8; floats with pre-Lenten lunar calendar","cruise-ship day-crowds congest San Miguel + nearer reefs — push early boats / south-zone sites"],"booking_lead":"peak dive weeks book well ahead; Chinchorro multi-day + private crewed dive-yacht = book months ahead (limited weather windows / small vessels)"},"jewels":[{"name":"Palancar Reef (Gardens/Caves/Bricks/Horseshoe)","si_tag":"Dive Globally","status":"future","bookable":"2-tank day-boat dive","tier":"essential","source":"https://www.torntackies.com/cozumel-dive-sites/","hook":"iconic coral pinnacles, archways, swim-throughs, 100-ft+ viz, accessible drift","si":"diveglobal","blurb":"iconic coral pinnacles, archways, swim-throughs, 100-ft+ viz, accessible drift","commission":"dive-op DMC + Viator affiliate","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","liveaboard":"destination","ocean":"destination"},"commission_lane":["operator","DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Santa Rosa Wall","si_tag":"Dive Globally","status":"future","bookable":"advanced day-boat dive (expert-only)","tier":"comfort","source":"https://www.torntackies.com/cozumel-dive-sites/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","hook":"starts ~15 m / 45 ft and drops into the deep; expert-level, with eagle rays, turtles, nurse sharks and giant morays","si":"diveglobal","blurb":"starts ~15 m / 45 ft and drops into the deep; expert-level, with eagle rays, turtles, nurse sharks and giant morays","when":"Dec-Mar","commission":"dive-op DMC","wells":["activities"],"wells_basis":"pass 2 — text","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","liveaboard":"destination","ocean":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Columbia Deep","si_tag":"Dive Globally","status":"future","bookable":"advanced day-boat dive","tier":"comfort","source":"https://cozumelscuba.com/cozumel-dive-sites/","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"diveglobal","when":"Dec-Mar","commission":"dive-op DMC","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["diveglobal"],"shelf_fit":{"diveglobal":"primary","liveaboard":"destination","ocean":"destination"},"commission_lane":["operator","DMC"],"commission_embedded":false,"commission_basis":"lane"},{"name":"Banco Chinchorro atoll","si_tag":"Dive Liveaboards","status":"future","bookable":"multi-day/liveaboard-style from Xcalak/Mahahual","tier":"premier","source":"http://www.pelagiclife.org/chinchorro","timing":"Dec-Mar","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"Dec-Mar","commission":"Aggressor/liveaboard reseller = Commissioned Agent on application","wells":["stay"],"wells_basis":"pass 2 — si (unambiguous spend type)","si_all":["liveaboard"],"shelf_fit":{"diveglobal":"destination","liveaboard":"primary","ocean":"destination"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed"},{"name":"Palancar snorkel + El Cielo sandbar","si_tag":"Ocean Adventures","status":"future","bookable":"catamaran/snorkel tour","tier":"essential","source":"https://cozumelscuba.com/cozumel-dive-sites/","hook":"reef snorkel and shallow turquoise sandbar, no-fly-free family option","si":"ocean","blurb":"reef snorkel and shallow turquoise sandbar, no-fly-free family option","commission":"Viator/GYG affiliate + DMC","wells":["activities"],"wells_basis":"derived from name/blurb/hook","si_all":["diveglobal","ocean"],"shelf_fit":{"diveglobal":"evidenced","liveaboard":"destination","ocean":"primary"},"commission_lane":["DMC","affiliate"],"commission_embedded":false,"commission_basis":"lane"}],"faq":[{"q":"What''s the real risk to plan for in Cozumel?","a":"Decompression discipline, not crime — this is a repetitive multi-day dive island. Follow DAN''s no-fly windows strictly (12h single, 18h multi-day, 24h conservative), because Cozumel''s day-boat profiles stack dives fast; the island has multiple chambers, but a bad no-fly call is the classic mistake. Also plan for dengue (repellent), bottled water and hurricane season (Jun–Nov).","source":"https://www.gov.uk/foreign-travel-advice/mexico","si_tag":"safety"},{"q":"Is drift diving in Cozumel dangerous?","a":"No, when you take the drift briefing seriously — but it is not passive. Expect a near-constant ~1.5-knot current that does the swimming for you; do a controlled descent, stay with the group and dive master, deploy an SMB, and dive within your certification. Santa Rosa Wall is expert-only; Palancar Gardens suits most certified divers.","source":"cozumelscuba.com, 2026-07-04","si_tag":"safety"},{"q":"What are the best dive sites in Cozumel, and can beginners dive them?","a":"Palancar Gardens is the everyone-friendly classic — coral pinnacles, archways and swim-throughs at 100-ft-plus visibility with mild current — while Santa Rosa Wall and Columbia Deep are advanced drifts. Beginners and newly certified divers do best at Palancar; Santa Rosa, dropping from ~15 m into the blue, is expert-only.","source":"torntackies.com, 2026-07-04","si_tag":"diveglobal"},{"q":"Can I do a liveaboard from Cozumel?","a":"Not from Cozumel itself — it is a day-boat island. True liveaboard-style multi-day diving goes to Banco Chinchorro, ~30–35 nm off Costa Maya, launched from Xcalak or Mahahual to the south, not Cozumel. The luxury alternative near Cozumel is a private crewed dive-yacht charter, since overnight liveaboards are effectively banned inside the national park.","source":"pelagiclife.org / islandlifemexico.com, 2026-07-04","si_tag":"liveaboard"},{"q":"Can non-divers snorkel Cozumel, and what''s the reef fee?","a":"Yes — the reef is superb for snorkelers, from Palancar shallows to the El Cielo starfish sandbar by catamaran. Everyone entering the marine park pays the reef bracelet, MX$220 (~US$13) per person per day as of Jan 2026; snorkel tours carry no no-fly restriction, making them a good last-day option before a flight.","source":"cozumelmio.com, 2026-07-04","si_tag":"ocean"},{"q":"Is Cozumel good for a honeymoon or a couples'' dive trip?","a":"Yes — it pairs world-class diving with real staffed villas. Luxury Cozumel and Villa Experience run oceanfront staffed homes (chef, concierge) from ~US$450/night, and there is no branded ultra flag on-island, so for hotel-brand luxury couples ferry to Mayakoba (Rosewood, Banyan Tree) ~an hour away.","source":"luxurycozumel.com, 2026-07-04","si_tag":"romance"},{"q":"When is the best time to dive Cozumel?","a":"December–March is peak, with the calmest seas, clearest skies and legendary 200-ft-plus visibility. November and May are the value sweet spots — near-peak conditions at ~25–40% (Nov) and ~20–30% (May) below Dec rates; May–September brings the warmest, calmest water (~27–28°C) but summer humidity and hurricane risk.","source":"sunsetcozumel.com / mexicotravelandleisure.com, 2026-07-04","si_tag":"planning"}],"seo":{"meta_title":"Cozumel Diving: Drift the Mesoamerican Reef","meta_description":"Cozumel is the Caribbean''s drift-diving crown - Palancar, Santa Rosa Wall and the Mesoamerican Reef, with chambers, no-fly rules and the Chinchorro liveaboard hook.","slug":"cozumel-mexico","primary_keyword":"Cozumel drift diving","long_tail":["Cozumel dive sites Palancar Santa Rosa","Cozumel marine park fee 2026","Banco Chinchorro liveaboard","Cozumel recompression chamber","Mesoamerican Barrier Reef diving"],"search_language":["en","es-MX"],"local_keywords":["buceo en Cozumel","arrecife Palancar Santa Rosa","camara hiperbarica Cozumel","buceo de deriva Cozumel","Parque Nacional Arrecifes de Cozumel","Banco Chinchorro buceo","villa privada de lujo Cozumel"],"hreflang":["en","es-MX"],"jsonld_type":"TouristDestination","content_freshness":"2026-07-04","attribution":{"author":{"type":"Organization","name":"TravelWell.World"},"publisher":{"type":"Organization","name":"TravelWell.World LLC"},"reviewed_by":{"type":"Organization","name":"TravelWell.World"},"digital_source_type":"CompositeWithTrainedAlgorithmicMediaDigitalSource","digital_source_vocab":"https://schema.org/IPTCDigitalSourceEnumeration","last_verified":"2026-07-04","last_verified_basis":"source_verified","verified_against":[{"name":"UK Foreign, Commonwealth & Development Office","url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","source_updated":"2026-07-16T16:08:09+01:00"}]}},"booking":{"advisory_updated":"2026-08-20","advisory_authority":"FCDO"},"si_checklist_25":null,"sis_present":[{"si":"diveglobal","status":"future"},{"si":"liveaboard","status":"future","note":"Cozumel = day-boat reef diving; liveaboard/multi-day runs to Banco Chinchorro launch from Xcalak/Mahahual, NOT Cozumel"},{"si":"ocean","status":"future"}],"ultra":[{"name":"Private Paradise Villa","location":"Cozumel (on-island)","what":"oceanfront exclusive-use villa, sleeps up to 24, 40+ staff incl. 7 rotating chefs + British-butler-trained butlers","why_ultra":"full-buyout fully-staffed private-resort — the on-island ultra expression","earning":"villa-agency/DMC commission on application (agent-of-record; no net-rate resale)","virtuoso_value_add":"n/a standalone; attach Virtuoso mainland stay for perks","mor_posture":"clean agent-side; red-flag any villa-inventory mark-up","price_tier":"ultra","source":"https://privateparadisevilla.com/"},{"name":"Private crewed dive-yacht charter","location":"Cozumel / Riviera Maya (on-water)","what":"fully-crewed private yacht (captain+deckhand+dive master, chef/hostess on premium boats), 15+ sites + El Cielo, premium open bar","why_ultra":"ultra dive expression; only luxury ''liveaboard-style'' the park''s vessel-size rules allow (overnight liveaboards effectively banned in-park)","earning":"charter/DMC commission on application","virtuoso_value_add":"n/a direct; pair with Virtuoso stay","mor_posture":"agent-of-record on charter; no net-rate resale","price_tier":"ultra","source":"https://dayyachtcharters.com/cozumel-yacht-charters-luxury-boat-rentals.html"},{"name":"Riviera Maya branded ultra (Rosewood/Banyan Tree Mayakoba, Chable Maroma, Maroma Belmond)","location":"Riviera Maya mainland (ferry + short transfer)","what":"Forbes/branded ultra-luxury resorts + villas; private pools, top spas, PGA course","why_ultra":"nearest true branded ultra flag — no ultra flag on Cozumel itself","earning":"Virtuoso preferred rate + commission (or via host-Virtuoso)","virtuoso_value_add":"upgrade, daily breakfast for two, early check-in/late check-out, ~US$100 credit, VIP welcome (Mayakoba flags)","mor_posture":"standard Virtuoso agent-of-record","price_tier":"ultra","source":"https://www.rosewoodhotels.com/en/mayakoba-riviera-maya"}],"source_verified":"2026-07-04","hero":{"query":"Cozumel, Mexico"},"geo":{"lat":20.423,"lng":-86.9223},"orbit":[{"id":"akumal-mexico","jewels":5,"si":["diveglobal","ocean","culture"]},{"id":"bacalar-mexico","jewels":6,"si":["tro