  ('espiritu-santo-island-mexico', '10S', 'Espíritu Santo Island', 'Mexico', 'Espíritu Santo island', 'live', 'verified', 'oceanAerial', 'Baja California Sur (Los Cabos & La Paz)', '{"expedition","ocean"}', '{}', '{"comfort","premier","luxury"}', null, null, '{"key_facts":["Uninhabited Sea-of-Cortez island, ~80.8 km2, off La Paz Baja California Sur","UNESCO Biosphere Reserve (1994) + World Heritage Site (2005) + Archipielago Espiritu Santo National Park (2007, ~479.9 km2)","CONANP permit (paper bracelet) required; open sunrise-sunset; permitted capacity managed (~40%)","Los Islotes: 600+ California sea lions, snorkel-only; colony closed Jun 1-Aug 31 (pupping)","NO lodging except permitted 8-tent Camp Cecil (Nov-Apr); day tours ~$100-150 pp, private sail ~$600+/boat"],"safety":{"emergency":"911","hospital":"NONE on-island (uninhabited, no cell service); boat to La Paz then Hospital Salvatierra/ISSSTE/private + air-evac; medical/evac insurance essential","malaria":"effectively none in Baja California Sur","dengue":"circulates in Mexico - use repellent","water":"carry own bottled/purified water - no services on-island","hurricane":"Jun-Nov - trip insurance for summer/fall","sea_lion":"SNORKEL ONLY, no-touch; Los Islotes closed Jun 1-Aug 31; keep guide distance from territorial bulls; licensed operator required","island_day_use":"NO services, NO cell, permit required, sunrise-sunset only, carry-in/carry-out, capacity managed","dive":"nearest hyperbaric chamber in La Paz (verify); DAN +1-919-684-9111; no-fly 18-24h; dive-within-cert; current on channel/open-water","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/mexico","read":"2026-08-20T14:49:02Z","page_updated":"2026-07-16T16:08:09+01:00","source_country":"mexico","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The city of Tijuana, in Baja California","lvl":3,"posture