asickness (long overnight Darwin/Wolf crossings roughest); extreme equatorial sun; DAN dive insurance with evac coverage effectively mandatory","fcdo":{"posture":"AREA-RESTRICTED","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/ecuador","read":"2026-08-20T14:53:32Z","page_updated":"2026-07-10T10:44:44+01:00","source_country":"ecuador","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","fcdo_zones":[{"name":"The Coastal Region provinces of Esmeraldas, Manabí, Santa Elena, Guayas, El Oro, Los Ríos and Santo Domingo de los Tsáchilas","lvl":3,"posture":"all-but-essential","except":["airside transit within Guayaquil Airport"],"note":"Gang-related violence linked to organised crime; the city of Guayaquil is inside this restriction."},{"name":"Within 20km of the Ecuador-Colombia border","lvl":3,"posture":"all-but-essential","except":["the El Ángel Ecological Reserve","the Rumichaca border crossing","the town of Tulcán","the Pan-American Highway (in Carchi province)"]}],"dive_emergency_numbers_verified":{"read":"2026-08-30","numbers":{"+1-919-684-9111":"DAN 24/7 emergency hotline — dan.org/about-dan/contact/, read 2026-08-30"},"_rule":"Each number above was read from the authority named beside it on the date shown. ⛔ A number with no entry here has NOT been verified and must not be presented as an emergency contact."}},"timing":{"type":"dive-calendar-two-season","dive_calendar":true,"warm_snorkel_season":"December-May (warmer water ~25-27C, calm seas, best snorkel/land wildlife; family + honeymoon)","big_marine_dive_season":"June-November (cool ~16-24C, strong currents; hammerhead schools + whale sharks at Darwin & Wolf)","peak":"July-August + whale-shark peak August-September + mid-December-early-January holidays","dive_curve_start":"2026-06-01","warm_curve_start":"2026-12-01","booking_lead_months":"6-12 (top liveaboard cabins + premium expedition suites; whale-shark weeks and holidays sell first)","shoulder_off_season_fill":"April-May and September-October","fire_date":"2026-05-18","trigger_date":"2026-05-18","secondary_fire_date":"2026-11-15","sharpen_note":"sharpen on live tracking — Aggressor / expedition-cruise availability feeds + hammerhead & whale-shark sighting logs; upwelling onset and pelagic aggregation shift yearly"},"jewels":[{"name":"Darwin''s Arch / Darwin Island","si_tag":"Dive Liveaboards/GEA","tier":"premier","source":"https://www.naturetripper.com/articles/whale-sharks-galapagos","timing":"July-August + whale-shark peak August-September + mid-December-early-January holidays","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"July-August + whale-shark peak August-September + mid-December-early-January holidays","commission":"own-CLIA / TCI Land Agency lane (Galápagos Aggressor III) — the moat","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Dive Liveaboards/GEA","diveglobal","expedition","liveaboard"],"shelf_fit":{"Dive Liveaboards/GEA":"evidenced","diveglobal":"evidenced","expedition":"evidenced","liveaboard":"primary"},"commission_lane":[],"commission_embedded":false,"commission_basis":"unparsed","si_raw":"Dive Liveaboards/GEA","si_map_basis":"normalised from free text ''Dive Liveaboards/GEA'' by gen_normalise_jewel_si"},{"name":"Wolf Island","si_tag":"Dive Liveaboards/GEA","tier":"premier","source":"https://www.dive-the-world.com/posts/darwin-wolf/galapagos-islands-diving-trips-darwin-and-wolf-islands.php","timing":"July-August + whale-shark peak August-September + mid-December-early-January holidays","when_source":"derived from destination timing","timing_type":"SEASONAL-WINDOW","si":"liveaboard","when":"July-August + whale-shark peak August-September + mid-December-early-January holidays","commission":"own-CLIA liveaboard lane — the moat","wells":[],"wells_basis":"text supports no Well — needs a human read","si_all":["Dive Liveaboard