  ('guanacaste-costa-rica', '10S', 'Guanacaste (Gold Coast)', 'Costa Rica', 'Costa Rica''s sunny Gold Coast', 'live', 'verified', 'tropicalBeach', 'Costa Rica', '{"tropical","expedition","liveaboard","wellness","wildlife"}', '{"tropical"}', '{"essential","comfort","premier","ultra"}', null, null, '{"key_facts":["Four Seasons Peninsula Papagayo spans 1,400 acres on an isthmus between two private beaches and holds 10 consecutive Forbes Five-Stars.","The Bat Islands'' ''Big Scare'' is the only bull-shark dive in Costa Rica; advanced (PADI AOW) minimum; bull-shark peak Jun-Oct.","Witch''s Rock (Roca Bruja) and Ollie''s Point sit inside Santa Rosa National Park, boat-access from Tamarindo/Coco/Flamingo.","Rincón de la Vieja National Park has active fumaroles, boiling mud pots, a volcancito, waterfalls and mineral hot springs.","Playa Grande / Las Baulas is the second-largest Pacific leatherback nesting beach on earth; nesting late-Oct-mid-Feb, peak Dec-Jan."],"safety":{"emergency":"911","hospital":"Nearest care: Liberia (Hospital Enrique Baltodano + CIMA-affiliated private clinics), ~30 min from Coco/Papagayo; major trauma to San Jose (CIMA / Clinica Biblica) with air evacuation","advisory_note":"Nov 25 2025 embassy alert on crime targeting foreigners; enroll STEP, do not resist robbery","book_enabled":true,"air_access_verified":"LIR — Daniel Oduber Quiros International Airport, Liberia — year-round US nonstops (Alaska LAX; American CLT/DFW/MIA; Delta ATL; JetBlue/Southwest/Sun Country); recent runway expansion","riptide":"Pacific rip currents; Tamarindo surf-injury risk — swim guarded/calm beaches (Conchal, Hermosa), beginner surf with instructor","volcano":"Rincon de la Vieja active/monitored — fumarole gas, thermal areas; marked trails + guided access only","dive":"Bat Islands advanced-only (strong currents, thermoclines, 30m+, bull sharks); no-fly-after-diving 18h/24h; DAN +1-919-684-9111","dengue":"endemic seasonal, higher in green/rainy months — use repellent","water":"generally potable incl. resort areas; default bottled in some rural/interior spots","fcdo":{"posture":"1","quotes":[],"url":"https://www.gov.uk/foreign-travel-advice/costa-rica","read":"2026-08-20T14:54:18Z","page_updated":"2026-05-19T11:42:25+01:00","source_country":"costa-rica","quotes_note":"not extracted by the join — a restricted-area clause is quoted by a human, never composed"},"posture":"book-freely","dive_emergency_numbers_verified":{"read":"2026-08-30","numbers":{"+1-919-684-9111":"DAN 24/7 emergency hotline — dan.org/about-dan/contact/, read 2026-08-30"},"_rule":"Each number above was read from the authority named beside it on the date shown. ⛔ A number with no entry here has NOT been verified and must not be presented as an emergency contact."}},"timing":{"peak":"mid-Dec-Apr (dry season; driest/sunniest region; April hottest)","shoulder":"Nov & late-Apr-early-May","green":"May-Nov (value + Bat Islands bull sharks Jun-Oct + leatherback nesting late-Oct-mid-Feb)","curve_start":"mid-December","booking_lead":{"christmas_easter":"~1 year ahead for peak-week resort inventory","weddings":"12-18 months for in-demand properties; 9-12 months minimum","dry_peak_general":"3-6 months for Jan-Mar coastal weeks"},"out_of_season_fill":"May-Nov: sell bull-shark diving (Jun-Oct), leatherback nesting (Oct-Feb), lush Rincón waterfalls, villa/resort value","fire_date":"late-November to early-December (dry/Christmas-Easter); weddings continuous 9-18mo forward; green+turtle+shark campaigns March-April","note":"sharpen lead-times + event windows on live booking-pace tracking before campaign lock","source":"https://worldlyadventurer.com/best-time-visit-guanacaste/","event_peaks":["Christmas-New Year","Semana Santa (Easter)","Guanacaste Day / Annexation (Jul 25)"]},"jewels":[{"name":"Papagayo Peninsula beaches","si_tag":"Tropical Islands / Beaches","status":"live","hook":"Private golden-sand beaches on a 1,400-acre gated luxury peninsula, calm Gulf water.","bookable_category